#include <iostream>
#include <vector>

int acumulado{0};

int contar_altos(std::vector<int> datos, int minimo) {
    for (int valor : datos) {
        if (valor >= minimo) {
            ++acumulado;
        }
    }
    return acumulado;
}

int main() {
    const int primera = contar_altos({2}, 2);
    const int segunda = contar_altos({}, 2);
    std::cout << primera << ':' << segunda;
    return 0;
}

