#include <vector>

int acumulado{0};

int contar_altos(std::vector<int> datos, int minimo) {
    // Repara el recuento sin cambiar el contrato ni las consultas.
    for (int valor : datos) {
        if (valor >= minimo) {
            ++acumulado;
        }
    }
    return acumulado;
}

int main() {
    const int primera = contar_altos({2}, 2);
    const int segunda = contar_altos({}, 2);
    std::cout << "Minimo:" << primera << ':' << segunda << '\n';

    const int tercera = contar_altos({8, 1, 5}, 5);
    const int cuarta = contar_altos({6, 7}, 5);
    const int quinta = contar_altos({}, 9);
    std::cout << "Nuevo:" << tercera << ':' << cuarta << ':' << quinta;
    return 0;
}

