#include <iostream>
#include <vector>

int acumulado{0};

int contar_altos(std::vector<int> datos, int minimo) {
    if (datos.empty()) {
        return 0;
    }
    for (int valor : datos) {
        if (valor >= minimo) {
            ++acumulado;
        }
    }
    return acumulado;
}

int main() {
    const int primera = contar_altos({8, 1, 5}, 5);
    const int segunda = contar_altos({6, 7}, 5);
    std::cout << primera << ':' << segunda;
    return 0;
}

